/// <summary>
///     AVA <c>parmlRicoSync</c> method.
/// </summary>
/// <param name="_parmValue">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean parmlRicoSync(boolean _parmValue = lRicoSync)
{
    lRicoSync = _parmValue;

    return lRicoSync;
}

/// <summary>
///     AVA <c>run</c> method.
/// </summary>
public void run()
{
    KCS_KBVBuildingProjectTable kcs_KBVBuildingProjectTable;
    NDX_KBVJobProt              nDX_KBVJobProt;
    NDX_KBVJobProt              nDX_KBVJobProGLB;

    #OCCRetryCount

    //Protokoll erzeugen
    if(!lRicoSync)
    {
        if(     this.parmKCS_KBVPotentialSalesVolType() == kcs_KBVPotentialSalesVolType::CrossCompany
            ||  this.parmKCS_KBVPotentialSalesVolType() == kcs_KBVPotentialSalesVolType::All)
        {
            nDX_KBVJobProGLB.createProt(NDX_KBVJob::KBV_UpdatePotSalesVolGLB, lJobMode);
        }

        if(     this.parmKCS_KBVPotentialSalesVolType() == kcs_KBVPotentialSalesVolType::CompanySpecific
            ||  this.parmKCS_KBVPotentialSalesVolType() == kcs_KBVPotentialSalesVolType::All)
        {
            nDX_KBVJobProt.createProt(NDX_KBVJob::KBV_UpdatePotSalesVol, lJobMode);
        }
    }

    try
    {

        while (queryRun.next())
        {
            if (queryRun.changed(tablenum(KCS_KBVBuildingProjectTable)))
            {
                kcs_KBVBuildingProjectTable = queryRun.get(tablenum(KCS_KBVBuildingProjectTable));

                if (    this.parmKCS_KBVPotentialSalesVolType() == kcs_KBVPotentialSalesVolType::CompanySpecific 
                    ||  this.parmKCS_KBVPotentialSalesVolType() == kcs_KBVPotentialSalesVolType::All)
                {
                    this.updateSalesVolumeLoc(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
                }

                if (    this.parmKCS_KBVPotentialSalesVolType() == kcs_KBVPotentialSalesVolType::CrossCompany
                    ||  this.parmKCS_KBVPotentialSalesVolType() == kcs_KBVPotentialSalesVolType::All)
                {
                //    this.updateSalesVolumeGLB(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
                    this.updateSalesVolumeGLB_v2(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
                }
            }
        }

    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                if (conLen(this.parmProcessingInterval()) > 0)
                {
                    error(strFmt("@NDX:NXABPUpdateConflictBatch",kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID));
                }
                else
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw;
        }
    }

    if(!lRicoSync)
    {
        if(     this.parmKCS_KBVPotentialSalesVolType() == kcs_KBVPotentialSalesVolType::CrossCompany
            ||  this.parmKCS_KBVPotentialSalesVolType() == kcs_KBVPotentialSalesVolType::All)
        {
            nDX_KBVJobProGLB.createProt(NDX_KBVJob::KBV_UpdatePotSalesVolGLB, lJobMode, false);
        }

        if(     this.parmKCS_KBVPotentialSalesVolType() == kcs_KBVPotentialSalesVolType::CompanySpecific
            ||  this.parmKCS_KBVPotentialSalesVolType() == kcs_KBVPotentialSalesVolType::All)
        {
            nDX_KBVJobProt.createProt(NDX_KBVJob::KBV_UpdatePotSalesVol, lJobMode, false);
        }
    }
}

/// <summary>
///     AVA <c>updateSalesVolumeGLB</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectID">
///     <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
void updateSalesVolumeGLB(KCS_KBVBuildingProjectID _kcs_KBVBuildingProjectID)
{
    KCS_KBVBuildingProjectTable     kcs_KBVBuildingProjectTable;
    KCS_KBVPotentialSalesVolumeGLB  kcs_KBVPotentialSalesVolumeGLB;

    container                       companies;
    container                       companiesAffected;
    AmountCur                       potentialSalesVol;
    CurrencyCode                    masterCurrency;

    masterCurrency  = KCS_KBVParameters::find().KCS_KBVCurrencyCode;
    companies       = AVAKBVBuildingProjectHelper::getAllBPCompanies();
    /*
    while select KCS_KBVBuildingProjectID 
    from    kcs_KBVBuildingProjectTable
    where   kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID == _kcs_KBVBuildingProjectID
    */
    kcs_KBVBuildingProjectTable = KCS_KBVBuildingProjectTable::find(_kcs_KBVBuildingProjectID);

    if(kcs_KBVBuildingProjectTable.RecId)
    {
        potentialSalesVol = 0.0;

        companiesAffected = AVABPJobsExecution::getCompaniesKCS_KBVPotentialSalesVolumeGLB(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
        if(companiesAffected != conNull())
        {
            potentialSalesVol = AVAKBVHelperClass::CalcPotentialSalesVolume(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID,
                                                                            companiesAffected,
                                                                            masterCurrency,
                                                                            NoYes::Yes);
        }

        kcs_KBVPotentialSalesVolumeGLB = KCS_KBVPotentialSalesVolumeGLB::find(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID, true);
        if (kcs_KBVPotentialSalesVolumeGLB)
        {
            if (    !(kcs_KBVPotentialSalesVolumeGLB.KCS_KBVPotentialSalesVolume    == potentialSalesVol)
                ||  !(kcs_KBVPotentialSalesVolumeGLB.CurrencyCode                   == masterCurrency))
            {
                if (updateKCS_KBVPotentialSalesVolumeTbl)
                {
                    ttsbegin;
                    kcs_KBVPotentialSalesVolumeGLB.KCS_KBVPotentialSalesVolume  = potentialSalesVol;
                    kcs_KBVPotentialSalesVolumeGLB.CurrencyCode                 = masterCurrency;
                    kcs_KBVPotentialSalesVolumeGLB.update();
                    ttscommit;
                }
            }
        }
        else
        {
            if (updateKCS_KBVPotentialSalesVolumeTbl)
            {
                ttsbegin;
                kcs_KBVPotentialSalesVolumeGLB.KCS_KBVBuildingProjectID     = kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
                kcs_KBVPotentialSalesVolumeGLB.KCS_KBVPotentialSalesVolume  = potentialSalesVol;
                kcs_KBVPotentialSalesVolumeGLB.CurrencyCode                 = masterCurrency;
                kcs_KBVPotentialSalesVolumeGLB.insert();
                ttscommit;
            }
        }
    }
}

/// <summary>
/// N.Freidenberger 07-08-2025
/// </summary>
/// <param name = "_kcs_KBVBuildingProjectID">_kcs_KBVBuildingProjectID</param>
void updateSalesVolumeGLB_v2(KCS_KBVBuildingProjectID _kcs_KBVBuildingProjectID)
{
    KCS_KBVPotentialSalesVolumeTbl    kbvPotensionSalesVolumeTbl;
    kcs_KBVPotentialSalesVolumeGLB    kcs_KBVPotentialSalesVolumeGLB;
    kcs_KBVPotentialSalesVolumeGLB    checkKBVPotentialSalesVolumeGLB;
    kcs_KBVPotentialSalesVolumeGLB    existKBVPotentionSalesVolumeGLB;
    boolean                           first = true;
    KCS_KBVBuildingProjectTable       kcs_KBVBuildingProjectTable = KCS_KBVBuildingProjectTable::find(_kcs_KBVBuildingProjectID);
    container                         companiesAffected;

    AmountCur                       potentialSalesVol;
    CurrencyCode                    masterCurrency;

    masterCurrency  = KCS_KBVParameters::find().KCS_KBVCurrencyCode;
  //  companies       = AVAKBVBuildingProjectHelper::getAllBPCompanies();

    if(kcs_KBVBuildingProjectTable.RecId)
    {
        companiesAffected = AVABPJobsExecution::getCompaniesKCS_KBVPotentialSalesVolumeGLB(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);

        select crosscompany: companiesAffected count (RecId) from  existKBVPotentionSalesVolumeGLB
            where existKBVPotentionSalesVolumeGLB.KCS_KBVBuildingProjectID == _kcs_KBVBuildingProjectID;

        if (existKBVPotentionSalesVolumeGLB.RecId > 0)
        {
            first = false;
        }

        select firstonly crosscompany: companiesAffected * from  kbvPotensionSalesVolumeTbl
            where kbvPotensionSalesVolumeTbl.KCS_KBVBuildingProjectID == _kcs_KBVBuildingProjectID
               join   checkKBVPotentialSalesVolumeGLB
            where checkKBVPotentialSalesVolumeGLB.KCS_KBVBuildingProjectID ==   kbvPotensionSalesVolumeTbl.KCS_KBVBuildingProjectID
               && checkKBVPotentialSalesVolumeGLB.ModifiedDateTime       <     kbvPotensionSalesVolumeTbl.ModifiedDateTime;

        if (checkKBVPotentialSalesVolumeGLB || first)
        {
            potentialSalesVol = 0.0;

            companiesAffected = AVABPJobsExecution::getCompaniesKCS_KBVPotentialSalesVolumeGLB(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
            if(companiesAffected != conNull())
            {
                potentialSalesVol = AVAKBVHelperClass::CalcPotentialSalesVolume(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID,
                                                                            companiesAffected,
                                                                            masterCurrency,
                                                                            NoYes::Yes);
            }

            kcs_KBVPotentialSalesVolumeGLB = KCS_KBVPotentialSalesVolumeGLB::find(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID, true);
            if (kcs_KBVPotentialSalesVolumeGLB)
            {
                if (    !(kcs_KBVPotentialSalesVolumeGLB.KCS_KBVPotentialSalesVolume    == potentialSalesVol)
                ||  !(kcs_KBVPotentialSalesVolumeGLB.CurrencyCode                   == masterCurrency))
                {
                    if (updateKCS_KBVPotentialSalesVolumeTbl)
                    {
                        ttsbegin;
                        kcs_KBVPotentialSalesVolumeGLB.KCS_KBVPotentialSalesVolume  = potentialSalesVol;
                        kcs_KBVPotentialSalesVolumeGLB.CurrencyCode                 = masterCurrency;
                        kcs_KBVPotentialSalesVolumeGLB.update();
                        ttscommit;
                    }
                }
            }
            else
            {
                if (updateKCS_KBVPotentialSalesVolumeTbl)
                {
                    ttsbegin;
                    kcs_KBVPotentialSalesVolumeGLB.KCS_KBVBuildingProjectID     = kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
                    kcs_KBVPotentialSalesVolumeGLB.KCS_KBVPotentialSalesVolume  = potentialSalesVol;
                    kcs_KBVPotentialSalesVolumeGLB.CurrencyCode                 = masterCurrency;
                    kcs_KBVPotentialSalesVolumeGLB.insert();
                    ttscommit;
                }
            }
        }

    }
}

/// <summary>
/// N.Freidenberger 07.08.2025
/// </summary>
/// <param name = "_buildingProjectId">_buildingProjectId</param>
/// <returns>boolean</returns>
public boolean isLocPotentialCalcNeeded(KCS_KBVBuildingProjectID        _buildingProjectId)
{
    boolean isneeded = false;

    KCS_KBVPotentialSalesVolumeTbl          kbvPotensionSalesVolumeTbl;
    SalesQuotationTable                     locsalesQuotationTable;
    KCS_KBVPotentialSalesVolumeTbl          existPotenSalesVolumeTbl;
    boolean                                 first = true;

    select count(RecId) from  existPotenSalesVolumeTbl
        where existPotenSalesVolumeTbl.KCS_KBVBuildingProjectID ==   locsalesQuotationTable.KCS_KBVBuildingProjectID;

    if (existPotenSalesVolumeTbl.RecID > 0)
    {
        first = false;
    }

    select firstonly locsalesQuotationTable
        where locsalesQuotationTable.KCS_KBVBuildingProjectID ==   _buildingProjectId
            join kbvPotensionSalesVolumeTbl
                where kbvPotensionSalesVolumeTbl.KCS_KBVBuildingProjectID == locsalesQuotationTable.KCS_KBVBuildingProjectID
                   && kbvPotensionSalesVolumeTbl.ModifiedDateTime < locsalesQuotationTable.ModifiedDateTime;

    if (locsalesQuotationTable.RecId || first)
    {
        isneeded = true;
    }

    return isneeded;
}

/// <summary>
///     AVA <c>updateSalesVolumeLoc</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectID">
///     <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
void updateSalesVolumeLoc(KCS_KBVBuildingProjectID  _kcs_KBVBuildingProjectID)
{
    KCS_KBVBuildingProjectTable     kcs_KBVBuildingProjectTable;
    //KCS_KBVBPCompanySpecific        kcs_KBVBPCompanySpecific;
    KCS_KBVPotentialSalesVolumeTbl  kcs_KBVPotentialSalesVolumeTbl;

    AmountCur                       potentialSalesVol;
    CurrencyCode                    masterCurrency;
    container                       companies;
    container                       companiesAffected;

    masterCurrency = KCS_KBVParameters::find().KCS_KBVCurrencyCode;
    companies = [curext()];
    /*
    while select KCS_KBVBuildingProjectID
    from    kcs_KBVBuildingProjectTable
    where   kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID == _kcs_KBVBuildingProjectID
    */
    if (this.isLocPotentialCalcNeeded(_kcs_KBVBuildingProjectID))
    {
        kcs_KBVBuildingProjectTable = KCS_KBVBuildingProjectTable::find(_kcs_KBVBuildingProjectID);

        if(kcs_KBVBuildingProjectTable.RecId)
        {
            potentialSalesVol = 0.0;

            companiesAffected = AVABPJobsExecution::getCompaniesKCS_KBVPotentialSalesVolumeTbl(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
            if(companiesAffected != conNull())
            {
                potentialSalesVol = AVAKBVHelperClass::CalcPotentialSalesVolume(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID,
                                                                            companiesAffected,
                                                                            masterCurrency,
                                                                            NoYes::No);
            }

            kcs_KBVPotentialSalesVolumeTbl = kcs_KBVPotentialSalesVolumeTbl::find(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID, true);
            if (kcs_KBVPotentialSalesVolumeTbl)
            {
                if (updateKCS_KBVPotentialSalesVolumeTbl)
                {
                    ttsbegin;
                    kcs_KBVPotentialSalesVolumeTbl.KCS_KBVPotentialSalesVolume  = potentialSalesVol;
                    kcs_KBVPotentialSalesVolumeTbl.CurrencyCode                 = masterCurrency;
                    kcs_KBVPotentialSalesVolumeTbl.update();
                    ttscommit;
                }
            }
            else
            {
                if (updateKCS_KBVPotentialSalesVolumeTbl)
                {
                    ttsbegin;
                    kcs_KBVPotentialSalesVolumeTbl.clear();
                    kcs_KBVPotentialSalesVolumeTbl.KCS_KBVBuildingProjectID     = kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
                    kcs_KBVPotentialSalesVolumeTbl.KCS_KBVPotentialSalesVolume  = potentialSalesVol;
                    kcs_KBVPotentialSalesVolumeTbl.CurrencyCode                 = masterCurrency;
                    kcs_KBVPotentialSalesVolumeTbl.insert();
                    ttscommit;
                }
            }
        }
    }
}
